  gallery=f'<section class="wrap shots" id="other-reviews"><p class="eyebrow">{T("ДРУГИЕ ИСТОЧНИКИ","OTHER SOURCES")}</p><h2>{T("Отзывы из других источников","Reviews from other sources")}</h2>'+(f'<div class="rc-list">{cards}</div>' if cards else '')+(f'<div class="shot-grid">{shots}</div>' if shots else '')+f'<dialog class="lightbox" id="lightbox"><button type="button" class="lightbox-close" aria-label="{T("Закрыть","Close")}">×</button><img alt=""></dialog></section>'
